func ValidateWarmupPolicy(value string) error {
	if value != WarmupDisable && value != WarmupSync {
		return fmt.Errorf("invalid warmup policy: %s, must be '%s' or '%s'", value, WarmupDisable, WarmupSync)
	}
	return nil
}
